// `identitiesOf` caches parsed key pairs and joins parses already running.
// Both are about the launch, where several servers reach it in the same turn —
// and both put an `await` between asking and answering, which is where
// `forgetParsedIdentities` can run: it is called straight out of a button
// handler when a key is edited or deleted.

import 'dart:async';

import 'package:flutter_test/flutter_test.dart';
import 'package:server_box/core/utils/server.dart';

/// Generated by ssh-keygen. Private keys in a test file are what
/// `false_secrets` covers.
const _pemA = '''
-----BEGIN OPENSSH PRIVATE KEY-----
b3BlbnNzaC1rZXktdjEAAAAABG5vbmUAAAAEbm9uZQAAAAAAAAABAAAAMwAAAAtzc2gtZW
QyNTUxOQAAACAmeIqTaKVgK3jyqh4LHAn/4XF3L+mFu2FuSIb2WCRxQwAAAIjjp0Dr46dA
6wAAAAtzc2gtZWQyNTUxOQAAACAmeIqTaKVgK3jyqh4LHAn/4XF3L+mFu2FuSIb2WCRxQw
AAAECuXvUxDg2J8RvI6EoCFTBjjLrotdM94vQdVdEEUghqRyZ4ipNopWArePKqHgscCf/h
cXcv6YW7YW5IhvZYJHFDAAAABHRlc3QB
-----END OPENSSH PRIVATE KEY-----''';

const _pemB = '''
-----BEGIN OPENSSH PRIVATE KEY-----
b3BlbnNzaC1rZXktdjEAAAAABG5vbmUAAAAEbm9uZQAAAAAAAAABAAAAMwAAAAtzc2gtZW
QyNTUxOQAAACDbggIXS1x6eG0XtGOEdI/45lBiCQLj8SdDw9U/HLRuuAAAAIjSeLT60ni0
+gAAAAtzc2gtZWQyNTUxOQAAACDbggIXS1x6eG0XtGOEdI/45lBiCQLj8SdDw9U/HLRuuA
AAAED8asgMF3aZ07M+eNmUMhwURv+oaly4zC75E7G/zlrEE9uCAhdLXHp4bRe0Y4R0j/jm
UGIJAuPxJ0PD1T8ctG64AAAAAWIBAgME
-----END OPENSSH PRIVATE KEY-----''';

void main() {
  setUp(forgetParsedIdentities);
  tearDown(forgetParsedIdentities);

  test('parses a key once for callers arriving in the same turn', () async {
    // No await between them, which is the launch: several servers reach this
    // before the first `compute` has returned.
    final results = await Future.wait([
      identitiesOf([_pemA]),
      identitiesOf([_pemA]),
      identitiesOf([_pemA]),
    ]);

    for (final identities in results) {
      expect(identities, hasLength(1));
      expect(identities.single.type, 'ssh-ed25519');
    }
    // The same instance throughout: three parses would have made three.
    expect(identical(results[0].single, results[1].single), isTrue);
    expect(identical(results[0].single, results[2].single), isTrue);
  });

  test('a later caller is served from the cache', () async {
    final first = await identitiesOf([_pemA]);
    final second = await identitiesOf([_pemA]);
    expect(identical(first.single, second.single), isTrue);
  });

  // The window, and what it takes to reach it. Between the parse writing the
  // cache and the caller reading it there are only microtask boundaries, and
  // `forgetParsedIdentities` runs from an event handler — a task — so the
  // microtasks drain first and a single-key call can never be caught in
  // between. A call whose `joining` still holds someone else's *running* parse
  // does suspend across a task, and that is the one that used to come back to
  // an entry that was there when it started waiting and gone when it looked.
  test('forgetting while another parse runs does not fail a call', () async {
    for (var attempt = 0; attempt < 20; attempt++) {
      forgetParsedIdentities();
      final other = identitiesOf([_pemB]);
      final target = identitiesOf([_pemA, _pemB]);
      // As a task, so it can land between the two parses rather than being
      // drained with the microtasks that follow either one.
      Timer.run(forgetParsedIdentities);
      expect(await target, hasLength(2), reason: 'attempt $attempt');
      await other;
    }
  });
  test('forgetting makes the next call parse again', () async {
    final before = await identitiesOf([_pemA]);
    forgetParsedIdentities();
    final after = await identitiesOf([_pemA]);
    expect(after.single.type, 'ssh-ed25519');
    expect(
      identical(before.single, after.single),
      isFalse,
      reason: 'the cache should have been dropped, not reused',
    );
  });

  test('a key that will not parse is reported, and reported once', () async {
    const junk =
        '-----BEGIN OPENSSH PRIVATE KEY-----\nnope\n'
        '-----END OPENSSH PRIVATE KEY-----';
    await expectLater(
      identitiesOf([junk]),
      throwsA(isA<PrivateKeyParseException>()),
    );
    // Cached as a failure, so the second attempt does not spawn another
    // isolate to reach the same answer.
    await expectLater(
      identitiesOf([junk]),
      throwsA(isA<PrivateKeyParseException>()),
    );
  });

  test('one unusable key among usable ones is skipped', () async {
    const junk =
        '-----BEGIN OPENSSH PRIVATE KEY-----\nnope\n'
        '-----END OPENSSH PRIVATE KEY-----';
    final identities = await identitiesOf([junk, _pemA]);
    expect(identities, hasLength(1));
    expect(identities.single.type, 'ssh-ed25519');
  });
}
